using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
namespace StarRacingPrototype {
 [InitializeOnLoad] public static class NativeRuntimePlayChecks {
  const string Key="StarRacing.NativeRuntime";static int startup,stage,assertions;static double deadline;static RaceDirector director;static LocalRaceConfig config;static bool had;static string prefs;static float volume;static int profile,ticks;static string identity;static int generation;static int[] revisions;static Keyboard keyboard;static string audioPreferences;
  static string Output=>Environment.GetEnvironmentVariable("STAR_RACING_NATIVE_RUNTIME_QA_DIR");
  static NativeRuntimePlayChecks(){EditorApplication.playModeStateChanged+=Changed;}
  public static void Run()=>Start(false);
  public static void RunSilentStartup()=>Start(true);
  public static void RunActivation()=>Start(false,true);
  static void Start(bool startupOnly,bool activationOnly=false){SessionState.SetBool(Key+"ActivationOnly",activationOnly);SessionState.SetBool(Key+"StartupOnly",startupOnly);if(!Environment.GetCommandLineArgs().Contains("-noaudio")||!Environment.GetCommandLineArgs().Contains("-muted"))throw new Exception("Native QA requires -noaudio -muted from startup");Directory.CreateDirectory(Output);var restore=Environment.GetEnvironmentVariable("STAR_RACING_NATIVE_PREFS_RESTORE_FILE");if(!string.IsNullOrEmpty(restore)){var saved=JsonUtility.FromJson<PreferenceBackup>(File.ReadAllText(restore));if(saved.existed)PlayerPrefs.SetString(LocalRaceConfig.PreferenceKey,saved.value);else PlayerPrefs.DeleteKey(LocalRaceConfig.PreferenceKey);PlayerPrefs.Save();}var physics=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/DynamicsManager.asset")[0]);File.WriteAllText(Path.Combine(Output,"loaded-physics.txt"),"broadphase="+physics.FindProperty("m_BroadphaseType").intValue+" fixedDeltaTime="+Time.fixedDeltaTime.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"\n");SessionState.SetBool(Key,true);SessionState.SetBool(Key+"Failed",false);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);startup=0;EditorApplication.update+=Enter;}
  static void Enter(){if(++startup<15)return;EditorApplication.update-=Enter;EditorApplication.isPlaying=true;}
  static void Check(bool ok,string why){assertions++;if(!ok)throw new Exception("Native runtime: "+why);}
  static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Key,false))return;if(state==PlayModeStateChange.EnteredPlayMode){had=PlayerPrefs.HasKey(LocalRaceConfig.PreferenceKey);prefs=PlayerPrefs.GetString(LocalRaceConfig.PreferenceKey);File.WriteAllText(Path.Combine(Output,"preferences-before.json"),JsonUtility.ToJson(new PreferenceBackup{existed=had,value=prefs}));audioPreferences=AudioPreferenceState();volume=AudioListener.volume;AudioListener.volume=0;deadline=EditorApplication.timeSinceStartup+1500;stage=assertions=profile=ticks=0;EditorApplication.update+=Step;}if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);EditorApplication.Exit(SessionState.GetBool(Key+"Failed",false)?1:0);}}
  [Serializable] sealed class PreferenceBackup{public bool existed;public string value;}
  public static void RunNeighbors(){Directory.CreateDirectory(Output);CloudlineChecks.RunConfigurationChecks();GraphAiChecks.Run();File.WriteAllText(Path.Combine(Output,"neighbors.txt"),"NATIVE_RUNTIME_NEIGHBORS_OK configuration graphAI exactLegacyAI=5400\n");}
  public static void RunAffected(){RunNeighbors();GraphCatalogRoutePlayChecks.Run();}
  public static void RunIntegrationContracts(){RunNeighbors();TrackProjectionParityChecks.Run();GraphEnvironmentChecks.Run();SilentStartupChecks.Run();File.WriteAllText(Path.Combine(Output,"integration-contracts.txt"),"INTEGRATION_CONTRACTS_OK graphAI independentMainLegacy projection environment silentStartup\n");}
  static string AudioPreferenceState(){
   const string prefix="StarRacing.Audio.";
   return string.Join("|",new[]{"Muted","Music","Engines","Effects"}.Select(k=>
    k+":"+PlayerPrefs.HasKey(prefix+k)+":"+(k=="Muted"?PlayerPrefs.GetInt(prefix+k,-1).ToString():PlayerPrefs.GetFloat(prefix+k,-1).ToString("R",System.Globalization.CultureInfo.InvariantCulture))));
  }
  static uint Seed(int wanted)=>Enumerable.Range(0,10000).Select(i=>(uint)i).First(s=>NativeTrackGenerator.FamilyFor(s,"cloud-city")=="path-choice"&&Procedural.GraphNativeCatalog.ProfileFor(s)==wanted);
  static void Step(){try{
   if(director!=null)Check(director.GetComponent<RaceAudioCoordinator>()==null,"noaudio persists through menu/preparation/race/repeat");
   if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Native runtime deadline");
   if(stage==0){bool activation=SessionState.GetBool(Key+"ActivationOnly",false);Check(new LocalRaceConfig().generatorRevision==12,"new configuration uses native12");keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();config=new LocalRaceConfig{humans=1,entrants=8,devices=new[]{-2,-1,0,1},theme="cloud-city",seed="77",generatorRevision=11};if(activation)config=new LocalRaceConfig{humans=1,entrants=8,devices=new[]{-2,-1,0,1},theme="cloud-city",seed=Seed(1).ToString(),jumps=true};config.Save();director=new GameObject("Real native director").AddComponent<RaceDirector>();director.gameObject.AddComponent<NativeHumanControlProbe>().director=director;Time.captureDeltaTime=.05f;Check(director.Course.GeneratorRevision==(activation?12:11)&&director.Course.IsIndependent==activation,"selected fresh or explicit legacy preview retained");Check(director.GetComponent<RaceAudioCoordinator>()==null,"noaudio startup does not initialize audio assets");Check(director.GetComponentsInChildren<AudioSource>(true).Length==0&&director.GetComponentsInChildren<AudioListener>(true).Length==0,"silent director creates no audio sources/listener");if(activation){
    Check(config.generatorRevision==12&&director.Track.GraphSurface!=null&&director.Cars.All(c=>c.GraphRoute!=null&&c.GraphRoute.Current),"fresh default prepares independent graph roster");
    Check(director.TryStartSelected(config.Copy(),out var activationError),"fresh default starts actual native runtime "+activationError);
    string activationIdentity=director.Course.ReplayIdentity(director.Track);int activationGeneration=director.RaceGeneration;
    Check(LocalRaceConfig.Load().generatorRevision==12&&LocalRaceConfig.Load().replay.fullIdentity==activationIdentity,"fresh default persists native identity");
    director.SetPaused(true);director.Restart();Check(director.RaceGeneration==activationGeneration+1&&director.Course.ReplayIdentity(director.Track)==activationIdentity,"default repeat retains full identity");director.SetPaused(true);
    Check(director.ExitToMenu()&&LocalRaceConfig.Load().generatorRevision==12,"default menu return retains selected revision");
    Check(AudioPreferenceState()==audioPreferences,"activation preserves audio preferences");
    File.WriteAllText(Path.Combine(Output,"result.txt"),"NATIVE12_ACTIVATION_OK newDefault actualMenu start grid fullIdentity repeat return preferencesRestored noPlayer\n");Finish(false);return;
   }if(SessionState.GetBool(Key+"StartupOnly",false)){
    var method=typeof(RaceDirector).GetMethod("StartupAudioDisabled",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);
    foreach(var args in new[]{new[]{"-muted"},new[]{"-noaudio"},new[]{"-muted","-noaudio"}})Check((bool)method.Invoke(null,new object[]{args}),"each quiet flag independently disables startup audio");
    Check(!(bool)method.Invoke(null,new object[]{new[]{"--seed","77"}}),"ordinary startup audio retained");
    Check(AudioPreferenceState()==audioPreferences,"muted startup preserves audio preferences");
    File.WriteAllText(Path.Combine(Output,"result.txt"),"SILENT_STARTUP_OK actualEditorPlayMode director coordinatorAbsent sourcesAbsent listenerAbsent -mutedIndependent -noaudioIndependent preferencesUnchanged noPlayer\n");Finish(false);return;}
   stage=1;return;}
   if(stage==1){profile++;config=new LocalRaceConfig{humans=1,entrants=8,devices=new[]{-2,-1,0,1},theme="cloud-city",seed=Seed(profile).ToString(),generatorRevision=12,jumps=true};Check(director.TryStartSelected(config,out var error),"native preparation "+error);Check(director.Course.IsIndependent&&director.Session.GraphCourse!=null,"graph actual session selected");Check(director.Cars.All(c=>c.GraphRoute!=null&&c.GraphRoute.Current),"all actual grid bindings");Check(director.Cars.All(c=>c.GraphRoute.Cursor.localPhysicalDistance<=350),"grid before firstgate and ramp");identity=config.replay.fullIdentity;Check(LocalRaceConfig.Load().replay.fullIdentity==identity,"full identity persisted");generation=director.RaceGeneration;revisions=director.Cars.Select(c=>c.PositionRevision).ToArray();ticks=0;stage=2;return;}
   if(stage==2){ticks++;if(ticks%20==0||director.Cars.Any(c=>c.IsFalling)){string rows=string.Join("\n",director.Cars.Select((c,i)=>$"profile={profile} update={ticks} sim={director.Session.Elapsed:R} id={i} road={c.GraphRoute.Cursor.roadId} local={c.GraphRoute.Cursor.localPhysicalDistance:R} progress={c.GraphRoute.CommonProgress:R} position={c.Body.position} velocity={c.Body.linearVelocity} revision={c.PositionRevision} initialRevision={revisions[i]} falling={c.IsFalling} requires={c.GraphRoute.RequiresRecovery} flying={c.GraphRoute.IsFlying} finished={director.Session.Racers[i].Finished} coasting={c.FinishedCoasting} grounded={c.Telemetry.grounded} desired={(i==0?director.GetComponent<NativeHumanControlProbe>().Driver:director.Drivers[i])?.DesiredSpeed} lane={(i==0?director.GetComponent<NativeHumanControlProbe>().Driver:director.Drivers[i])?.Lane} limit={(i==0?director.GetComponent<NativeHumanControlProbe>().Driver:director.Drivers[i])?.SpeedLimitSource} blocker={(i==0?director.GetComponent<NativeHumanControlProbe>().Driver:director.Drivers[i])?.LimitingEntrant} motorSpeed={HumanHandlingForces.Observe(c.Body.linearVelocity,c.Body.rotation*Vector3.forward,c.Body.angularVelocity,c.Frame).Speed:R} lateral={Vector3.Dot(c.Body.position-c.Frame.position,c.Frame.right):R} input={JsonUtility.ToJson(c.CurrentInput)}"))+"\n";File.AppendAllText(Path.Combine(Output,"trace.txt"),rows);}Check(director.Cars.All(c=>!c.IsFalling),"ordinary pack retains route");if(director.Session.Elapsed>60)Check(director.Cars.All(c=>c.GraphRoute.CommonProgress>700),"all eight ordinary controls clear first optional runway without deadlock");if(director.Session.Phase!=RacePhase.Results)return;Check(director.Session.Racers.Any(r=>r.Finished),"actual ordinary AI crosses allnative gates");Check(director.Cars.Select((c,i)=>c.PositionRevision==revisions[i]).All(v=>v),"no recovery/per-tick pose authority");File.WriteAllText(Path.Combine(Output,"profile-"+profile+".txt"),$"NATIVE_REAL_PACK_OK profile={profile} seed={config.seed} seconds={director.Session.Elapsed} finishers={director.Session.Racers.Count(r=>r.Finished)} entrants=8 identity={identity} ordinaryControls=1 CCD=8\n");director.SetPaused(true);stage=3;return;}
   if(stage==3){director.Restart();Check(director.RaceGeneration==generation+1&&director.Course.ReplayIdentity(director.Track)==identity,"repeat content and generation");director.SetPaused(true);Check(director.ExitToMenu(),"return menu");var oldTrack=director.Track;var oldCars=director.Cars;int oldGeneration=director.RaceGeneration;foreach(bool badSchema in new[]{false,true}){var bad=config.Copy();if(badSchema)bad.replay.schema=99;else bad.replay.fullIdentity=new string('0',64);Check(!director.TryStartSelected(bad,out var error)&&error.Length>0,"foreign fullidentity/schema denied");Check(director.Track==oldTrack&&director.Cars==oldCars&&director.RaceGeneration==oldGeneration&&!director.Started,"failure leaves existing preview/runtime intact");}if(profile<4){stage=1;return;}stage=4;return;}
   if(stage==4){foreach(int revision in new[]{10,11}){var legacy=new LocalRaceConfig{humans=1,entrants=8,devices=new[]{-2,-1,0,1},theme="cloud-city",seed="7",generatorRevision=revision};Check(director.TryStartSelected(legacy,out var error),"explicitlegacy runtime "+error);Check(director.Course.GeneratorRevision==revision&&director.Track.GraphSurface==null&&director.Cars.All(c=>c.GraphRoute==null)&&director.Session.GraphCourse==null,"explicitold physical/runtime route");director.SetPaused(true);director.ExitToMenu();}Check(AudioPreferenceState()==audioPreferences,"noaudio preserves existing audio preference values and presence");File.WriteAllText(Path.Combine(Output,"silent-startup.txt"),"NOAUDIO_STARTUP_SESSION_OK coordinatorAbsent sourcesAbsent preferencesUnchanged EditorPlayMode noPlayer\n");File.WriteAllText(Path.Combine(Output,"result.txt"),$"NATIVE_RUNTIME_PLAY_OK assertions={assertions} profiles=4 ordinary8carpack including ordinary-input human proxy repeated fullidentity rollback explicit10/11 noPlayer\n");Finish(false);}
  }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(Output,"failure.txt"),e.ToString());Finish(true);}}
  static void Finish(bool failed){EditorApplication.update-=Step;SessionState.SetBool(Key+"Failed",failed);if(had)PlayerPrefs.SetString(LocalRaceConfig.PreferenceKey,prefs);else PlayerPrefs.DeleteKey(LocalRaceConfig.PreferenceKey);PlayerPrefs.Save();if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);keyboard=null;AudioListener.volume=volume;Time.timeScale=1;EditorApplication.isPlaying=false;}
 }
 [DefaultExecutionOrder(-50)] public sealed class NativeHumanControlProbe:MonoBehaviour {
  public RaceDirector director;AiDriver driver;public AiDriver Driver=>driver;DrivingInput command;int ticks,generation=-1;
  void FixedUpdate(){if(director==null||director.Paused||!director.Started||director.GraphWorld==null)return;if(generation!=director.RaceGeneration){generation=director.RaceGeneration;driver=new AiDriver(0,DriverProfile.Racer,77,director.Balance);ticks=0;command=default;}if(!director.Session.CanDrive(0)){director.Cars[0].SetInput(default);return;}if(++ticks%10==0||!director.GraphWorld[0].Valid)command=driver.StepGraph(director.GraphWorld,.1f);director.Cars[0].SetInput(driver.ApplyGraphControl(director.Cars[0],command,Time.fixedDeltaTime));}
 }
}
